-- Fichier 3/3 : box, paires et inscriptions. Répétable, sans secrets.
BEGIN;
DO $padel_pairs$
DECLARE
 v_row jsonb; v_category text; v_number integer; v_source_a text; v_source_b text; v_player_a text; v_player_b text; v_pair text; v_box text;
 v_aliases jsonb := '{"fred-romain":"frederic-romain","kevin-tulpinck":"kevin-tulpinckx"}'::jsonb;
BEGIN
 FOR v_row IN SELECT value FROM jsonb_array_elements('[["OPEN",1,"stephane-zone","gauvain-callens"],["OPEN",1,"junior-decock","fabrice-claes"],["OPEN",1,"timothe-desmoudt","laurent-oyhenard"],["OPEN",1,"brian-smet","herve-vandy"],["OPEN",1,"max-zone","vincent-denis-piou"],["OPEN",1,"malcolm-gossart","maxence-gysemberg"],["OPEN",1,"michael-bertrand","charley"],["OPEN",2,"loic-houart","thomas-vandenkerkhoven"],["OPEN",2,"kevin-de-troyer","massimo-morchio"],["OPEN",2,"kevin-tulpinckx","tom-groeseneken"],["OPEN",2,"jean-francois-smal","brice-jeanmotte"],["OPEN",2,"reda-abayahia","mike-liroux"],["OPEN",2,"gijs-klarenbeek","luc-copin"],["OPEN",2,"pierre-van-cleuvenbergen","axel-van-cleuvenbergen"],["OPEN",3,"maxime-romain","fred-romain"],["OPEN",3,"anthony-guenne","gaetan-moens"],["OPEN",3,"bertrand-govoerts","noel-parate"],["OPEN",3,"daniel-laduron","alain-laduron"],["OPEN",3,"olivier-engels","serge-kreusch"],["OPEN",3,"romain-deschutter","guillaume-dessy"],["OPEN",4,"lucas-pistone","gaetan-celestri"],["OPEN",4,"christian-pierre","alain-piens"],["OPEN",4,"devashish-basnet","jean-louis-dufour"],["OPEN",4,"christian-vanschoonwinkel","laurent-deschutter"],["OPEN",4,"greg-cachoir","cedric-ronsmans"],["OPEN",4,"serge-locquet","didier-vanherck"],["OPEN",5,"john-falzone","yannick-van-thienen"],["OPEN",5,"jean-michel-hanquin","cedric-quintin"],["OPEN",5,"claude-paulus","gerard-delatte"],["OPEN",5,"fabrice-degreef","milo-degreef"],["OPEN",5,"jonathan-waerzeggers","lionel-waerzeggers"],["OPEN",5,"baudouin-van-ruymbeke","jean-michel-jerome"],["WOMEN_MIXED",1,"manon","charley"],["WOMEN_MIXED",1,"michael-bertrand","camille-dierickx"],["WOMEN_MIXED",1,"heloise-fontaine","malcolm-gossart"],["WOMEN_MIXED",1,"aurelie-gardette","frederic-romain"],["WOMEN_MIXED",1,"loic-houart","lola-leysen"],["WOMEN_MIXED",1,"julie-paix","junior-decock"],["WOMEN_MIXED",2,"laura-bertrand","kevin-tulpinck"],["WOMEN_MIXED",2,"lola-leysen","manon"],["WOMEN_MIXED",2,"stephanie-vanderhofstadt","aurelie-gardette"],["WOMEN_MIXED",2,"gil-de-poerck","leila-de-poerck"],["WOMEN_MIXED",2,"gisele-bertholet","david-dierickx"],["WOMEN_MIXED",2,"nathalie-naome","alain-laduron"],["WOMEN_MIXED",3,"els-lips","kim-bardiau"],["WOMEN_MIXED",3,"julie-paix","gisele-bertholet"],["WOMEN_MIXED",3,"an-dodion","daniel-laduron"],["WOMEN_MIXED",3,"jessica-vanderhaegen","pierre-van-cleuvenbergen"],["WOMEN_MIXED",3,"christine-evrard","charlotte-krugg"],["WOMEN_MIXED",4,"frederic-romain","adele-dengis"],["WOMEN_MIXED",4,"devashish-basnet","chantal"],["WOMEN_MIXED",4,"gael-smets","meghann-vander-wee"],["WOMEN_MIXED",4,"laurent-van-innes","brigitte-somville"],["WOMEN_MIXED",4,"elodie-cuvelie","pierre-antoine-briol"],["WOMEN_MIXED",4,"romain-deschutter","celine-jammart"],["WOMEN_MIXED",5,"sandrine-delimont","frederic-mahy"],["WOMEN_MIXED",5,"jessica-vanderhaegen","sandrine-nockreman"],["WOMEN_MIXED",5,"juliette-bertin","sandrine-van-ysendyck"],["WOMEN_MIXED",5,"frederique-callebaut","jennifer-chaparro"],["WOMEN_MIXED",5,"maxime-romain","madeline-hayot"],["WOMEN_MIXED",5,"an-dodion","julie-collin"],["WOMEN_MIXED",6,"virginie-dalcq","lucrezia-olivo"],["WOMEN_MIXED",6,"veronique-genot","patricia-gebala"],["WOMEN_MIXED",6,"nancy-van-deynse","greta-antoons"],["WOMEN_MIXED",6,"jennifer-chaparro","yannick-van-thienen"],["WOMEN_MIXED",6,"laurence-walravens","katherline-lamine"],["WOMEN_MIXED",6,"celine-jammart","adele-dengis"]]'::jsonb) LOOP
  v_category := v_row->>0; v_number := (v_row->>1)::integer; v_source_a := v_row->>2; v_source_b := v_row->>3;
  v_player_a := COALESCE(v_aliases->>v_source_a,v_source_a); v_player_b := COALESCE(v_aliases->>v_source_b,v_source_b);
  v_pair := CASE WHEN v_source_a COLLATE "C" < v_source_b COLLATE "C" THEN v_source_a||'__'||v_source_b ELSE v_source_b||'__'||v_source_a END;
  v_box := '2026-1-'||v_category||'-'||v_number;
  INSERT INTO boxes(id,cycle_id,category,number) VALUES(v_box,'2026-1',v_category,v_number) ON CONFLICT(id) DO NOTHING;
  INSERT INTO pairs(id,player1,player2) VALUES(v_pair,v_player_a,v_player_b) ON CONFLICT(id) DO NOTHING;
  INSERT INTO entries(id,pair_id,box_id) VALUES(v_box||'__'||v_pair,v_pair,v_box) ON CONFLICT(id) DO NOTHING;
 END LOOP;
END;
$padel_pairs$;
COMMIT;
SELECT (SELECT count(*) FROM players) AS joueurs, (SELECT count(*) FROM pairs) AS paires, (SELECT count(*) FROM boxes) AS box, (SELECT count(*) FROM entries) AS inscriptions;
-- FIN DU FICHIER 3
